# ساخت content/ch8.js (فصل ۸: استودیوی خلاق) با همان قالب HTML فصل‌های دیگر
import json, sys

def card(title, body, cls="card"): return f'<div class="{cls}"><div class="ch"><h3>{title}</h3></div>{body}</div>'
def p(t): return f"<p>{t}</p>"
def li(t): return f'<div class="li"><span class="dot"></span><div>{t}</div></div>'
def lis(items): return "".join(li(i) for i in items)
def rule(title, t, extra=""): return f'<div class="card dk"><div class="ch"><h3>{title}</h3></div><div style="font-size:12pt;font-weight:700">{t}</div>{extra}</div>'
def bubble(q): return f'<div class="bubble u" style="max-width:100%"><div style="font-size:8pt;font-weight:700;color:var(--muted)">پرسش تو</div>«{q}»</div>'
def flow(nodes): return '<div class="flow">' + '<span class="arr">◂</span>'.join(f'<div class="node">{n}</div>' for n in nodes) + "</div>"
def cell(): return '<span class="cell" data-w="1"></span>'
def write(tall=False): return '<div class="write tall" data-w="1"></div>' if tall else '<div class="write" data-w="1"></div>'
def table(head, rows, cells=0):
    h = "".join(f"<th>{x}</th>" for x in head)
    r = "".join("<tr>" + "".join(f"<td>{c}</td>" for c in row) + ("".join(f"<td>{cell()}</td>" for _ in range(cells))) + "</tr>" for row in rows)
    return f'<table class="tw"><tr>{h}</tr>{r}</table>'
EXPLORE_NOTE = "این فعالیت را با یک ابزار مجاز برای سن خودت انجام بده، مثل ChatGPT یا ویرا، و با کمک یک بزرگسال. نام، سن و اطلاعات شخصی خودت را در پرسش‌ها ننویس. اگر ابزار نداری، از شبیه‌ساز آفلاین همین درس استفاده کن یا همین کار را با معلم یا والدین و روی کاغذ انجام بده."

def lesson(day, title, name, mission, tip, learn, explore, investigate, create, ch, refl, prog):
    secs = [{"key": "learn", "html": learn}, {"key": "explore", "html": explore}, {"key": "investigate", "html": investigate}]
    if create: secs.append({"key": "create", "html": create})
    return {"day": day, "title": title, "name": name, "mission": mission, "tip": tip, "sections": secs,
            "challenges": [{"level": i + 1, "ages": a, "html": f"<p>{t}</p>"} for i, (a, t) in enumerate(zip(["۱۱ سال", "۱۲ سال", "۱۳ سال"], ch))],
            "reflect": refl, "progress": prog}


def labbtn(href, t): return f'<p><a class="btn primary" href="{href}">{t}</a></p>'
